style.css:
@-moz-document url("https://www.duolingo.com/") {
@font-face {
  font-family: 'UD Digi Kyokasho NK-R';
  src: url('https://microftfiledump.blob.core.windows.net/dump/UDDigiKyokashoNK-R.woff2') format('woff2');
  unicode-range: U+3040–9FBF;
  }
@font-face {
    font-family: din-round, sans-serif;
    unicode-range: U+0000-00FF;
}
*{
  font-family: din-round, 'UD Digi Kyokasho NK-R', sans-serif;
  font-size: max(1em, 18pt);
}
[lang="ja"]{
  font-size: max(1em, 24pt);
}
span{
  font-weight: 400 !important;
  }
}
